from datetime import datetime, timedelta
from functools import partial
from funcy import cache, SkipMemoization, reraise

calls = []
@cache(60, key_func=lambda x: x)
def cached(x):
    calls.append(x)
    if x < 0:
        raise cached.skip('uncached')
    if x == 0:
        raise cached.skip()
    return x * 2

assert cached.memory == {}
assert cached.skip is SkipMemoization
assert cached(2) == cached(2) == 4
assert calls == [2]
assert cached.memory[2][0] == 4
cached.memory[2] = (7, datetime.now())
assert cached(2) == 7
cached.memory[2] = (7, datetime.now() - timedelta(seconds=61))
assert cached(2) == 4
assert cached(-1) == cached(-1) == 'uncached'
assert cached(0) is None
assert -1 not in cached.memory and 0 not in cached.memory
memory = cached.memory
cached.invalidate(2)
assert memory == {}
cached(3)
cached.invalidate_all()
assert cached.memory is memory and not memory

seen = []
def transform(exc, prefix='converted'):
    seen.append(exc)
    return RuntimeError(prefix, str(exc))

original = ValueError('original')
try:
    with reraise(ValueError, transform):
        raise original
except RuntimeError as exc:
    assert exc.args == ('converted', 'original')
    assert exc.__cause__ is original
assert seen == [original]

@reraise(ValueError, partial(transform, prefix='decorated'))
def fail(message):
    raise ValueError(message)
for message in ('first', 'second'):
    try:
        fail(message)
    except RuntimeError as exc:
        assert exc.args == ('decorated', message)
        assert str(exc.__cause__) == message

class CallableError(Exception):
    def __call__(self, exc):
        raise AssertionError('Exception instances must not be called')

for target in (RuntimeError, RuntimeError('fixed'), CallableError('callable')):
    try:
        with reraise(ValueError, target):
            raise original
    except RuntimeError as exc:
        if target is RuntimeError:
            assert exc.args == ()
        else:
            assert exc is target
    except CallableError as exc:
        assert exc is target

with reraise(ValueError, lambda exc: (_ for _ in ()).throw(AssertionError())):
    pass
try:
    with reraise(ValueError, transform):
        raise KeyError('unmatched')
except KeyError:
    pass
else:
    raise AssertionError('Unmatched exception was swallowed')
print('Targeted cache and reraise checks passed')
